query:
SELECT ?object ?objectLabel ?orbitalPeriod ?orbitalPeriodLabel WHERE {
  VALUES ?type { wd:Q634 wd:Q405 }  # planet oder Mond
  ?object wdt:P31 ?type.
  OPTIONAL { ?object wdt:P2146 ?orbitalPeriod. }
  FILTER(?object != wd:Q525)  # Sonne separat
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en,de". }
} UNION {
  # Sonne explizit
  BIND(wd:Q525 AS ?object)
  OPTIONAL { ?object wdt:P2146 ?orbitalPeriod. }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en,de". }
}
ORDER BY ?objectLabel
LIMIT 100
